<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Bot, CircleStop, FileDown, Image, LoaderCircle, MessageSquareText, Plus, Search, Send, Trash2, WandSparkles } from 'lucide-vue-next'
import AppShell from '../components/AppShell.vue'
import MarkdownContent from '../components/MarkdownContent.vue'
import { cancelTask, continueTask, deleteTask, fetchConversation, fetchMe, fetchTask, fetchTasks, routeMessage, taskDownloadUrl } from '../api'
import type { AuthUser, ConversationMessage, TaskInfo } from '../types'

const router=useRouter(), route=useRoute(); const user=ref<AuthUser>(); const tasks=ref<TaskInfo[]>([]); const selected=ref<TaskInfo>(); const messages=ref<ConversationMessage[]>([]); const prompt=ref(''); const busy=ref(false); const mode=ref<'chat'|'pptagent'>('chat'); const web=ref(false); const images=ref(false); const error=ref(''); const timeline=ref<string[]>([]); let source: EventSource | undefined
const activeTitle=computed(()=>selected.value?.query || '新的创作会话')
const sorted=computed(()=>[...tasks.value].sort((a,b)=>Date.parse(b.updated_at||b.created_at)-Date.parse(a.updated_at||a.created_at)))
function taskLabel(status: string){return ({running:'生成中',completed:'已交付',failed:'需要处理',conversation:'对话中',cancelled:'已取消'} as Record<string,string>)[status]||status}
function closeStream(){source?.close();source=undefined}
async function loadTasks(){tasks.value=await fetchTasks()}
async function select(task: TaskInfo){closeStream();selected.value=task;error.value='';const session=await fetchConversation(task.id);messages.value=session.messages||[];if(session.full_answer&&!messages.value.some(m=>m.role==='assistant'&&m.content===session.full_answer))messages.value.push({role:'assistant',content:session.full_answer,timestamp:''});if(session.conversation_streaming||task.status==='running') openStream(task.id,session.replay_after_event_id||session.latest_event_id||0)}
function openStream(id:string, after=0){closeStream();busy.value=true;const url=`/api/tasks/${id}/stream${after?`?after_id=${after}`:''}`;source=new EventSource(url);const receive=(event:MessageEvent)=>consume(event.data);for(const type of ['answer','answer_end','system_step','tool_call','progress','error','complete','continue_complete','continue_queued','conversation_complete'])source.addEventListener(type,receive);source.onerror=()=>{closeStream();busy.value=false;refreshSelected()}}
function consume(raw:string){try{const data=JSON.parse(raw) as {type?:string;content?:string;error?:string;message?:string;status?:string;done?:number;total?:number;files?:string[];phase_detail?:string};if(data.type==='answer'){const last=messages.value[messages.value.length-1];if(last?.role==='assistant')last.content+=data.content||'';else messages.value.push({role:'assistant',content:data.content||'',timestamp:new Date().toISOString()})}else if(data.type==='error'){error.value=data.error||'任务出现错误'}else if(data.type==='system_step'||data.type==='tool_call'||data.type==='progress'){if(data.phase_detail||data.message)timeline.value=[data.phase_detail||data.message||'正在推进任务',...timeline.value].slice(0,5)}else if(['answer_end','complete','continue_complete','conversation_complete'].includes(data.type||'')){busy.value=false;closeStream();refreshSelected()} }catch{ /* Ignore keepalive or malformed transport fragments. */ }}
async function refreshSelected(){await loadTasks();if(selected.value){const renewed=tasks.value.find(t=>t.id===selected.value?.id);if(renewed)selected.value=renewed}}
async function submit(){const text=prompt.value.trim();if(!text||busy.value)return;error.value='';messages.value.push({role:'user',content:text,timestamp:new Date().toISOString()});prompt.value='';busy.value=true;await nextTick();try{if(selected.value?.status==='completed'||selected.value?.status==='failed'||selected.value?.status==='cancelled'){const result=await continueTask(selected.value.id,text);openStream(result.task_id,result.after_event_id||0)}else{const result=await routeMessage(text,selected.value?.id||'',mode.value,web.value,images.value);if(!selected.value){await loadTasks();const created=tasks.value.find(t=>t.id===result.task_id);if(created)selected.value=created}if(result.reply)messages.value.push({role:'assistant',content:result.reply,timestamp:new Date().toISOString()});openStream(result.task_id,result.after_event_id||0)}}catch(e){error.value=e instanceof Error?e.message:'无法提交这条消息';busy.value=false}}
async function remove(id:string){if(!confirm('删除这个会话及其交付文件？'))return;await deleteTask(id);if(selected.value?.id===id){selected.value=undefined;messages.value=[]}await loadTasks()}
async function stop(){if(selected.value){await cancelTask(selected.value.id);closeStream();busy.value=false;await refreshSelected()}}
function newConversation(){closeStream();selected.value=undefined;messages.value=[];timeline.value=[];error.value='';prompt.value=String(route.query.brief||'');router.replace({query:{}})}
onMounted(async()=>{try{user.value=await fetchMe();await loadTasks();const brief=String(route.query.brief||'');const requested=String(route.query.task||'');if(brief)newConversation();else { const target=tasks.value.find(task=>task.id===requested)||tasks.value[0]; if(target)await select(target) }}catch(e){error.value=e instanceof Error?e.message:'加载工作台失败'}});onBeforeUnmount(closeStream);watch(()=>route.query.brief,v=>{if(v)newConversation()})
</script>
<template><AppShell title="创作工作台" subtitle="对话、规划与交付在同一条轨迹里" :email="user?.email" :guest="user?.is_guest" @new="newConversation"><template #header><button class="compose-link" @click="router.push('/compose')"><WandSparkles :size="16" />编排页面</button></template><div class="workbench"><aside class="conversations"><div class="conversation-head"><span>你的会话</span><button @click="newConversation" aria-label="新建会话"><Plus :size="17" /></button></div><div class="task-list"><button v-for="task in sorted" :key="task.id" class="task-row" :class="{selected:task.id===selected?.id}" @click="select(task)"><span class="status-dot" :class="task.status"></span><span class="task-info"><b>{{ task.query || '未命名会话' }}</b><small>{{ taskLabel(task.status) }} · {{ task.total_count ? `${task.done_count}/${task.total_count} 页` : '对话' }}</small></span><Trash2 :size="14" class="delete" @click.stop="remove(task.id)" /></button><p v-if="!tasks.length" class="empty-list">还没有会话。<br>从右侧写下第一个想法。</p></div></aside><section class="canvas"><header class="canvas-head"><div><span class="canvas-kicker">{{ selected ? taskLabel(selected.status) : '准备就绪' }}</span><h2>{{ activeTitle }}</h2></div><div v-if="selected" class="canvas-actions"><button v-if="selected.status==='running'" class="outline-button" @click="stop"><CircleStop :size="15" />停止</button><a v-for="file in selected.files" :key="file" class="download" :href="taskDownloadUrl(selected.id,file)"><FileDown :size="15" />下载</a></div></header><div class="messages"><div v-if="!messages.length" class="blank-canvas"><span><Bot :size="25" /></span><h3>从一个问题开始。</h3><p>可以让它解释、梳理资料，或直接开始一份演示。明确需求会让成稿更接近你的表达。</p><div><button @click="prompt='为一场产品发布会规划 8 页叙事'">规划一份发布会演示</button><button @click="prompt='总结这份资料的核心观点'">先梳理一个主题</button></div></div><article v-for="(message,index) in messages" :key="index" class="message" :class="message.role"><div class="message-label">{{ message.role==='user'?'你':'Deckform' }}</div><MarkdownContent :content="message.content" /></article><div v-if="busy" class="thinking"><LoaderCircle :size="17" />正在组织这段内容</div></div><div v-if="timeline.length" class="activity"><span>工作轨迹</span><p v-for="item in timeline" :key="item">{{ item }}</p></div><form class="composer" @submit.prevent="submit"><div class="modebar"><button type="button" :class="{on:mode==='chat'}" @click="mode='chat'"><MessageSquareText :size="14" />对话</button><button type="button" :class="{on:mode==='pptagent'}" @click="mode='pptagent'"><WandSparkles :size="14" />PPT 生成</button><label><input v-model="web" type="checkbox">联网资料</label><label><input v-model="images" type="checkbox"><Image :size="13" />图片参考</label></div><div class="composer-input"><textarea v-model="prompt" rows="2" :disabled="busy" placeholder="写下你想完成的事…" @keydown.enter.exact.prevent="submit"/><button type="submit" :disabled="busy||!prompt.trim()"><Send :size="18" /></button></div><p v-if="error" class="inline-error">{{ error }}</p></form></section></div></AppShell></template>
<style scoped>
.compose-link{margin-left:auto;display:flex;align-items:center;gap:6px;border:1px solid rgba(162,210,212,.24);border-radius:6px;padding:8px 10px;color:#bfe6df;background:#0e2b37;font-size:12px}.workbench{height:calc(100vh - 78px);display:grid;grid-template-columns:254px minmax(0,1fr)}.conversations{display:flex;flex-direction:column;border-right:1px solid rgba(213,235,245,.1);background:#0b1a27}.conversation-head{display:flex;align-items:center;justify-content:space-between;padding:20px 16px 14px;color:#bdd0d9;font-size:12px}.conversation-head button{display:grid;place-items:center;width:27px;height:27px;color:#97eee0;background:#15414a;border:0;border-radius:5px}.task-list{overflow:auto;padding:0 8px 16px}.task-row{position:relative;width:100%;display:flex;align-items:center;gap:8px;padding:11px 7px;border:0;border-radius:6px;color:#aabec7;background:transparent;text-align:left}.task-row:hover,.task-row.selected{background:#15303e;color:#eef8f6}.task-info{min-width:0;flex:1}.task-info b,.task-info small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.task-info b{font-size:13px;font-weight:600}.task-info small{margin-top:3px;color:#76919e;font-size:11px}.status-dot{width:7px;height:7px;border-radius:50%;background:#718895}.status-dot.running{background:#66e1ca;box-shadow:0 0 0 4px rgba(102,225,202,.1)}.status-dot.completed{background:#74c5ee}.status-dot.failed{background:#e98e89}.delete{opacity:0;color:#e9a3a0}.task-row:hover .delete{opacity:1}.empty-list{padding:18px 8px;color:#647d89;font-size:12px;line-height:1.7}.canvas{position:relative;display:grid;grid-template-rows:auto minmax(0,1fr) auto auto;background:#0c1d2a}.canvas-head{display:flex;justify-content:space-between;gap:20px;padding:21px 30px;border-bottom:1px solid rgba(213,235,245,.1)}.canvas-kicker{font:500 10px 'DM Mono',monospace;color:#71d6c4;letter-spacing:.08em}.canvas-head h2{max-width:690px;margin:4px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:700 18px 'Noto Serif SC',serif}.canvas-actions{display:flex;align-items:center;gap:8px}.outline-button,.download{display:flex;align-items:center;gap:5px;padding:7px 9px;border:1px solid #466473;border-radius:5px;color:#b3cbd0;background:transparent;font-size:12px}.download{color:#082b36;background:#72e0c9;border-color:#72e0c9}.messages{overflow:auto;padding:32px max(25px,7%)}.blank-canvas{max-width:570px;margin:8vh auto;text-align:center}.blank-canvas>span{display:grid;place-items:center;width:53px;height:53px;margin:auto;color:#63ddc7;background:#123b48;border-radius:16px 16px 4px 16px}.blank-canvas h3{margin:19px 0 9px;font:700 28px 'Noto Serif SC',serif}.blank-canvas p{margin:auto;max-width:450px;color:#8da4af;font-size:14px;line-height:1.8}.blank-canvas div{display:flex;justify-content:center;gap:8px;margin-top:25px}.blank-canvas button{border:1px solid #315260;border-radius:5px;padding:8px 10px;color:#b6cbd2;background:#102a36;font-size:12px}.message{max-width:760px;margin:0 auto 28px;padding:18px 20px;border-radius:3px 13px 13px 13px}.message.user{max-width:650px;margin-right:0;color:#d9edf0;background:#173846}.message.assistant{color:#243d45;background:#f0f1e9}.message-label{margin-bottom:10px;font:500 10px 'DM Mono',monospace;letter-spacing:.08em;color:#56928b}.message.user .message-label{color:#94d7ce}.thinking{display:flex;gap:8px;align-items:center;max-width:760px;margin:0 auto;color:#8cd9ca;font-size:13px}.thinking svg{animation:spin 1s linear infinite}.activity{max-height:110px;overflow:auto;margin:0 30px;padding:10px 14px;border-left:2px solid #44aa9b;background:#0a2631;color:#9bbbc1;font-size:12px}.activity span{color:#6ce5ca;font:10px 'DM Mono',monospace}.activity p{margin:5px 0 0}.composer{padding:14px 30px 20px}.modebar{display:flex;align-items:center;gap:5px;margin:0 0 7px}.modebar button,.modebar label{display:flex;align-items:center;gap:4px;border:0;padding:5px 7px;color:#76929d;background:transparent;font-size:11px}.modebar button.on{color:#85ebd8;background:#123b47;border-radius:4px}.modebar label{margin-left:5px}.modebar input{accent-color:#5edbc5}.composer-input{display:grid;grid-template-columns:1fr 43px;gap:8px;padding:8px;background:#eff2e9;border-radius:8px}.composer textarea{width:100%;min-height:39px;resize:none;padding:6px 8px;border:0;outline:0;color:#18333d;background:transparent;line-height:1.5}.composer-input button{display:grid;place-items:center;align-self:end;height:39px;border:0;border-radius:5px;color:#f3fbf6;background:#0e6670}.composer-input button:disabled{opacity:.4}.inline-error{margin:7px 0 0;color:#f4aaa1;font-size:12px}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:850px){.workbench{grid-template-columns:1fr}.conversations{display:none}.canvas-head,.composer{padding-left:18px;padding-right:18px}.messages{padding:22px 18px}.message{padding:15px}.modebar label{display:none}} 
</style>
